using System.Collections.Concurrent;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal static class TaskPileContextOpportunity
{
    private sealed class Counts
    {
        public long Piles, CardVisits, EligibleCardVisits, HitCardVisits, LargePileCardVisits, LargePileHitCardVisits;
    }
    private static readonly ConcurrentDictionary<string, Counts> Totals = new();

    static TaskPileContextOpportunity()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            string? path = Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_PILE_CONTEXT_OUT");
            if (path is null) return;
            File.WriteAllText(path, JsonSerializer.Serialize(Totals.OrderBy(x => x.Key).ToDictionary(x => x.Key,
                x => new { x.Value.Piles, x.Value.CardVisits, x.Value.EligibleCardVisits, x.Value.HitCardVisits,
                    x.Value.LargePileCardVisits, x.Value.LargePileHitCardVisits }), new JsonSerializerOptions { WriteIndented = true }));
        };
    }

    internal static void Observe(SimPlayerCombatState state, StrategicEffectRequirements requirements, bool skillsExhaust)
    {
        ObservePile(state.DiscardPile, requirements, skillsExhaust);
        ObservePile(state.DrawPile, requirements, skillsExhaust);
        ObservePile(state.Hand, requirements, skillsExhaust);
    }

    private static void ObservePile(SimCardPile pile, StrategicEffectRequirements requirements, bool skillsExhaust)
    {
        var opportunity = pile.TaskObserveStrategicAggregate((int)requirements, skillsExhaust);
        Counts counts = Totals.GetOrAdd($"{requirements}|skillsExhaust={skillsExhaust}|pile={pile.Type}", static _ => new());
        int count = pile.Cards.Count;
        Interlocked.Increment(ref counts.Piles);
        Interlocked.Add(ref counts.CardVisits, count);
        if (opportunity.Eligible) Interlocked.Add(ref counts.EligibleCardVisits, count);
        if (opportunity.Hit) Interlocked.Add(ref counts.HitCardVisits, count);
        if (count >= 128)
        {
            Interlocked.Add(ref counts.LargePileCardVisits, count);
            if (opportunity.Hit) Interlocked.Add(ref counts.LargePileHitCardVisits, count);
        }
    }
}

