using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text.Json;
using CombatSolver.Engine.Common;

namespace CombatSolver;

internal static class TaskProjectionRecheckCensus
{
    [ThreadStatic] private static long[]? _counts;
    private static readonly ConcurrentBag<long[]> Cells = new();
    private static readonly ConcurrentQueue<string> MultipleWriteStacks = new();
    private static int _stacks;
    private static readonly string[] Names = ["FullScan", "CleanHit", "DirtyCheck", "DirtyRejected", "DirtyRetained",
        "FirstDirtyMark", "RepeatedSameCardMark", "MultipleCardFallback", "NonemptyFallback", "NoCacheToMark", "StructuralInvalidation"];

    static TaskProjectionRecheckCensus()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            string? output = Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_PROJECTION_RECHECK_OUT");
            if (output is null) return;
            long[] sums = new long[Names.Length * 2];
            foreach (long[] cell in Cells)
                for (int i = 0; i < sums.Length; i++) sums[i] += cell[i];
            var totals = Enumerable.Range(0, Names.Length).ToDictionary(i => Names[i],
                i => new { Calls = sums[i * 2], CardWeightedCalls = sums[i * 2 + 1] });
            File.WriteAllText(output, JsonSerializer.Serialize(new { Totals = totals, MultipleWriteStacks = MultipleWriteStacks.ToArray(),
                ThreadCells = Cells.Count, Scope = "read-only counts, not timing or pruning evidence" }, new JsonSerializerOptions { WriteIndented = true }));
        };
    }

    internal static void Record(int kind, SimCardPile pile)
    {
        long[]? counts = _counts;
        if (counts is null) { _counts = counts = new long[Names.Length * 2]; Cells.Add(counts); }
        counts[kind * 2]++;
        counts[kind * 2 + 1] += pile.Cards.Count;
        if (kind == 7 && Interlocked.Increment(ref _stacks) <= 8)
            MultipleWriteStacks.Enqueue(pile.Type + " count=" + pile.Cards.Count + Environment.NewLine + new StackTrace(false));
    }
}

