using System.Reflection;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static int AssertRuntimeCardClassAbsence(
        CombatPredictionSimulator parent, CombatRootSnapshot root, Player player)
    {
        int checks = 0;
        var subscribers = (PredictionModHookSubscriberCapture)typeof(SimulatedCombatState)
            .GetField("_modHookSubscribers", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(parent.State.CombatState)!;
        MirroredHookListenerFilter filter = subscribers.MirroredHookFilter;
        FieldInfo cache = typeof(SimCardPile).GetField("_runtimeCardClasses",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        if (!filter.CanCacheCardRuntimeClasses)
            throw new InvalidOperationException("Native runtime-class certificate was unexpectedly rejected.");
        string parentBefore = DescribeContinuationContractState(parent, root, player);
        SimCardPile draw = parent.State.GetPlayerCombatState(player).DrawPile;
        if (draw.MayContainRuntimeCardClass(filter, RuntimeCardClass.SovereignBlade | RuntimeCardClass.Wither))
            throw new InvalidOperationException("Ordinary root cards did not certify absent classes.");
        object shared = cache.GetValue(draw)!;

        void Check(SimCardPile pile)
        {
            foreach (RuntimeCardClass kind in new[] { RuntimeCardClass.SovereignBlade, RuntimeCardClass.Wither })
            {
                bool actual = pile.MayContainRuntimeCardClass(filter, kind);
                bool present = pile.Cards.Any(card => kind == RuntimeCardClass.SovereignBlade
                    ? card.Preview is SovereignBlade : card.Preview is Wither);
                if (present && !actual)
                    throw new InvalidOperationException("Runtime class cache certified a false absence.");
                Interlocked.Increment(ref checks);
            }
        }

        CombatPredictionSimulator[] siblings = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        Parallel.For(0, siblings.Length, index =>
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator candidate = siblings[index];
            CombatPredictionSimulator oracle = parent.Fork();
            DisableMirroredFilterForOracle(oracle);
            SimCardPile childDraw = candidate.State.GetPlayerCombatState(player).DrawPile;
            if (!ReferenceEquals(cache.GetValue(childDraw), shared))
                throw new InvalidOperationException("Fork did not share immutable class metadata.");
            Check(childDraw);
            void MutatePair(Action<CombatPredictionSimulator> action)
            {
                foreach (CombatPredictionSimulator simulator in new[] { candidate, oracle })
                {
                    action(simulator);
                    ((SimulatedCombatState)simulator.State.CombatState).NormalizePowerCardState(simulator);
                }
                foreach (SimCardPile pile in candidate.State.GetPlayerCombatState(player).AllPiles)
                    Check(pile);
                if (DescribeContinuationContractState(candidate, root, player)
                    != DescribeContinuationContractState(oracle, root, player))
                    throw new InvalidOperationException("Class-based normalization changed complete branch state/history/RNG.");
            }
            MutatePair(simulator => simulator.State.GetPlayerCombatState(player).DrawPile.TopCard!
                .MutablePreview.BaseReplayCount++);
            if (!ReferenceEquals(cache.GetValue(childDraw), shared))
                throw new InvalidOperationException("A class-preserving COW write discarded class metadata.");
            MutatePair(simulator => simulator.AddToPile(
                PredictedCard.Create(ModelDb.Card<SovereignBlade>(), player), PileType.Draw, CardPilePosition.Top));
            MutatePair(simulator => ((SimulatedCombatState)simulator.State.CombatState)
                .SetAmount<SwordSagePower>(player.Creature, index + 1));
            MutatePair(simulator => simulator.AddToPile(
                simulator.State.GetPlayerCombatState(player).DrawPile.TopCard!, PileType.Discard));
            MutatePair(simulator => simulator.AddToPile(
                PredictedCard.Create(ModelDb.Card<Wither>(), player), PileType.Exhaust));
            MutatePair(simulator => simulator.State.GetPlayerCombatState(player).DrawPile
                .Insert(0, PredictedCard.Create(ModelDb.Card<SovereignBlade>(), player)));
            string childBefore = DescribeContinuationContractState(candidate, root, player);
            CombatPredictionSimulator grandchild = candidate.Fork();
            CombatPredictionSimulator grandOracle = oracle.Fork();
            foreach (CombatPredictionSimulator simulator in new[] { grandchild, grandOracle })
            {
                simulator.State.GetPlayerCombatState(player).DrawPile.Clear();
                ((SimulatedCombatState)simulator.State.CombatState).SetAmount<SwordSagePower>(player.Creature, 0);
                ((SimulatedCombatState)simulator.State.CombatState).NormalizePowerCardState(simulator);
            }
            Check(grandchild.State.GetPlayerCombatState(player).DrawPile);
            if (grandchild.State.GetPlayerCombatState(player).DrawPile.MayContainRuntimeCardClass(filter,
                    RuntimeCardClass.SovereignBlade | RuntimeCardClass.Wither)
                || DescribeContinuationContractState(grandchild, root, player)
                    != DescribeContinuationContractState(grandOracle, root, player)
                || DescribeContinuationContractState(candidate, root, player) != childBefore)
                throw new InvalidOperationException("Class cache clear/removal escaped second-generation isolation.");
        });
        if (!ReferenceEquals(cache.GetValue(draw), shared)
            || DescribeContinuationContractState(parent, root, player) != parentBefore)
            throw new InvalidOperationException("Class cache escaped parent isolation.");

        PredictedCard alias = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        SimCardPile first = new(PileType.Draw, new[] { alias });
        Check(first);
        SimCardPile second = new(PileType.Hand, new[] { alias });
        alias.MutablePreview.BaseReplayCount++;
        alias.MaterializePreview();
        Check(first);
        Check(second);
        Check(first.Clone());
        Check(new SimCardPile(PileType.Exhaust, new[] {
            new PredictedCard(alias.Original, ModelDb.Card<Wither>().ToMutable()) }));
        if (!first.MayContainRuntimeCardClass(new MirroredHookListenerFilter(enabled: false), RuntimeCardClass.Wither))
            throw new InvalidOperationException("Disabled certificate did not preserve the full scan.");
        var alternative = new MirroredHookListenerFilter(enabled: true);
        object beforeAlternative = cache.GetValue(first)!;
        first.MayContainRuntimeCardClass(alternative, RuntimeCardClass.Wither);
        if (ReferenceEquals(cache.GetValue(first), beforeAlternative))
            throw new InvalidOperationException("Class cache crossed root certificates.");

        Harmony harmony = new("CombatSolver.Tests.RuntimeCardClassGuard");
        MethodInfo prefix = typeof(UnattendedTestRunner).GetMethod(nameof(ProjectedGetterPrefix),
            BindingFlags.Static | BindingFlags.NonPublic)!;
        foreach (MethodInfo method in new[] {
            typeof(PredictedCard).GetProperty(nameof(PredictedCard.Preview))!.GetMethod!,
            typeof(PredictionUtils).GetMethod(nameof(PredictionUtils.CloneCardStateForSimulation))! })
        {
            try
            {
                harmony.Patch(method, prefix: new HarmonyMethod(prefix));
                MirroredHookListenerFilter rejected = MirroredHookListenerFilter.Capture();
                if (rejected.CanCacheCardRuntimeClasses
                    || !first.MayContainRuntimeCardClass(rejected, RuntimeCardClass.Wither))
                    throw new InvalidOperationException("An unknown getter/clone patch retained absence certification.");
            }
            finally { harmony.Unpatch(method, prefix); }
        }
        return checks;
    }
}

