using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text.Json;
using CombatSolver.Engine.Common;
namespace CombatSolver;
internal static class TaskEmptyProjectionCensus
{
    [ThreadStatic] private static long[]? _counts;
    private static readonly ConcurrentBag<long[]> Cells = new();
    private static readonly string[] Names = ["FullScan", "CleanHit", "DirtyCheck", "DirtyRetained", "DirtyRejected", "MembershipAttempt", "MembershipRetained", "MembershipFallback", "ContainsCheck", "FirstDirtyMark", "SameDirtyMark", "MultipleDirtyFallback", "NonemptyMarkFallback", "NoCacheMark", "OpaqueQuery", "FilterRejectedQuery", "OwnerAliasQuery", "FullInvalidation"];
    static TaskEmptyProjectionCensus()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            string? output = Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_EMPTY_PROJECTION_OUT");
            if (output is null) return;
            long[] sums = new long[Names.Length * 2 + 1];
            foreach (long[] cell in Cells) for (int i = 0; i < sums.Length; i++) sums[i] += cell[i];
            var totals = Enumerable.Range(0, Names.Length).ToDictionary(i => Names[i], i => new { Calls = sums[i * 2], CardWeightedCalls = sums[i * 2 + 1] });
            File.WriteAllText(output, JsonSerializer.Serialize(new { Totals = totals, QueryThreadWallMilliseconds = sums[^1] * 1000.0 / Stopwatch.Frequency, ThreadCells = Cells.Count, Scope = "process-wide diagnostic; cumulative query thread wall time including instrumentation, not CPU or performance acceptance" }, new JsonSerializerOptions { WriteIndented = true }));
        };
    }
    private static long[] GetCounts()
    {
        if (_counts is { } counts) return counts;
        _counts = new long[Names.Length * 2 + 1]; Cells.Add(_counts); return _counts;
    }
    internal static void Record(int kind, SimCardPile pile)
    {
        long[] counts = GetCounts(); counts[kind * 2]++; counts[kind * 2 + 1] += pile.Cards.Count;
    }
    internal static bool Contains(SimCardPile pile, List<PredictedCard> cards, PredictedCard card)
    { Record(8, pile); return cards.Contains(card); }
    internal static Measurement Measure() => new(Stopwatch.GetTimestamp());
    internal readonly struct Measurement(long started) : IDisposable
    { public void Dispose() => GetCounts()[^1] += Stopwatch.GetTimestamp() - started; }
}

